import itertools
from typing import List, Dict, Any


def has_independent_set(instance: Dict[str, Any]) -> bool:
    n = instance["n"]
    edges = set()
    for u, v in instance["edges"]:
        edges.add(frozenset((u, v)))
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    # brute force all subsets of size k
    for subset in itertools.combinations(range(n), k):
        ok = True
        for i in range(k):
            for j in range(i + 1, k):
                if frozenset((subset[i], subset[j])) in edges:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            return True
    return False
EOF"}

